import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { describe, expect, it } from 'vitest';
import { headingSlug, scanFields } from '../src/fields';

// Same vectors as the Go checker (mlcext/testdata/fields.json, generated by
// mlcext's TestFieldVectors): display and rules recognise fields identically.
const vectors = JSON.parse(
  readFileSync(resolve(process.cwd(), '../../mlcext/testdata/fields.json'), 'utf8'),
) as { markdown: string; fields: Record<string, unknown>[]; errors: Record<string, unknown>[] }[];

describe('field scanner = mlcext', () => {
  for (const [i, v] of vectors.entries()) {
    it(`vector ${i + 1}: ${JSON.stringify(v.markdown.slice(0, 40))}`, () => {
      const s = scanFields(v.markdown);
      const fields = s.fields.map((f) => ({
        kind: f.kind, name: f.name, named: f.named, value: f.value, chars: f.chars, rows: f.rows,
        fillPage: f.fillPage, pattern: f.pattern, tooltip: f.tooltip, line: f.line, col: f.col,
      }));
      expect(fields).toEqual(v.fields);
      expect(s.errors).toEqual(v.errors);
    });
  }
});

describe('headingSlug = mlcmd2pdf heading_slug', () => {
  it.each([
    ['EV-2026-0666 · Kritisch', 'ev-2026-0666--kritisch'],
    ['Übersicht der Messwerte', 'übersicht-der-messwerte'],
    ['1. Ziel & Zweck (v2)', '1-ziel--zweck-v2'],
    ['snake_case ✅', 'snake_case-'],
  ])('%s', (input, want) => expect(headingSlug(input)).toBe(want));
});
